<template><div><UsabilityView v-if="usabilityEnabled"/><Card v-else><h2>经营资格</h2><StatusPanel :error="error" :loading="loading"/><div class="s1-toolbar"><Input v-model="targetStore" placeholder="店铺编号" style="width:240px"/><Input v-model="categoryId" placeholder="商品类目编号（可选）" style="width:230px"/><Button type="primary" @click="reload">按当前事实计算</Button></div><EligibilityCard :value="selected"/><RecordDetail v-if="selected" :value="{sourceVersions:selected.sourceVersions}"/><Table v-if="!selected" :data="records" :columns="columns" no-data-text="暂无商户"><template slot="action" slot-scope="{row}"><Button @click="targetStore=row.id;reload()">查看资格</Button></template></Table><Page v-if="!selected" :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;loadStores()"/></Card></div></template>
<script>import {usabilityEntry} from './usability/enabled';import {leaveGuard} from './usability/entry';import UiView from './usability/Eligibility';import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import EligibilityCard from './EligibilityCard';import RecordDetail from './RecordDetail';const LegacyView = {mixins:[pageMixin],components:{StatusPanel,EligibilityCard,RecordDetail},data:()=>({targetStore:'',categoryId:'',columns:[{title:'商户',key:'storeName'},{title:'编号',key:'id'},{title:'操作',slot:'action'}]}),mounted(){if(this.usabilityEnabled)return;this.loadStores();},methods:{loadStores(){return this.load('/stores');},async reload(){if(!this.targetStore){this.selected=null;return this.loadStores();}this.loading=true;this.error='';try{this.selected=await s1Read('/stores/'+this.targetStore+'/eligibility',{categoryId:this.categoryId||undefined});}catch(e){this.selected=null;this.error=e.message;}finally{this.loading=false;}}}};LegacyView.mixins.push(usabilityEntry);LegacyView.components={...LegacyView.components,UsabilityView:UiView};LegacyView.beforeRouteLeave=leaveGuard;LegacyView.beforeRouteUpdate=leaveGuard;export default LegacyView;</script><style scoped>.s1-toolbar{display:flex;gap:12px;margin:18px 0}</style>
